def conjugate {G : Type*} [Group G] (x : G) (H : Subgroup G) : Subgroup G where
  carrier    := {a : G | ∃ h, h ∈ H ∧ a = x * h * x⁻¹}
  one_mem'   := ⟨1, H.one_mem, H.inv_mem (H.one_mem)⟩

def conjugate {G : Type*} [Group G] (x : G) (H : Subgroup G) : Subgroup G where
  //prime-section parameter
  ⟨{ _ := by simp [λ h, ⟨h, Set.MapsTo.right _ (Set.MapsTo.left_of_mem H h), rfl⟩ }, _⟩

theorem conjugate {G : Type*} [Group G] (x : G) (H : Subgroup G) : Subgroup G := by
  intro a h;
  exact ⟨x * h, ⟨h.1, h.2, rfl⟩⟩

def conjugate {G : Type*} [Group G] (x : G) (H : Subgroup G) : Subgroup G where
  carrier := {a : G | ∃ h, h ∈ H ∧ a = x * h * x⁻¹}
  one_mem'  := by

theorem conjugate_one (H : Subgroup G) : conjugate 1 H = H   := by
  ext x
  simp [conjugate]</');

lemma aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K  := by
  calc
  Nat.card (G ⧸ H) * Nat.card H = Nat.card G := by rw [← H.index_eq_card, H.index_mul_card];
  _ = Nat.card K * Nat.card H := by rw [h', mul_comm];
  exact Nat.eq_of_mul_eq_mul_right Nat.card_pos this

lemma aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K  := by
  calc Nat.card (G ⧸ H) * Nat.card H = Nat.card G := by rw [← H.index_eq_card, H.index_mul_card];
  simp only [h', mul_comm, Nat.mul_right_eq_mul₁_iff];
  exact Nat.eq_of_mul_eq_mul_right Nat.card_pos _

theorem eq_of_mul_eq_mul_right {n m k : Nat} (hm : 0 < m) (h : n * m = k * m) : n = k  := by
  rw [← Nat.mul_comm n m, ↦ mul_comm] at h;
  exact Nat.eq_of_mul_eq_mul_left hm h

lemma aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K  := by
  rw [← H.index_eq_card, H.index_mul_card, h', mul_comm] at ⊢;
